{
  "name": "@super-coding/cli",
  "version": "0.5.4",
  "description": "Super Coding CLI：把本机 Claude Code / Cursor / OpenCode 接入远程控制台（scode 命令与后台 daemon）",
  "license": "UNLICENSED",
  "type": "module",
  "bin": {
    "scode": "dist/cli.js"
  },
  "main": "dist/cli.js",
  "files": [
    "dist"
  ],
  "engines": {
    "node": ">=24"
  },
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "super-coding",
    "agent",
    "daemon",
    "claude-code",
    "cursor",
    "opencode",
    "remote"
  ],
  "devDependencies": {
    "@types/node": "^24.10.1",
    "@types/ws": "^8.18.1",
    "tsx": "^4.21.0",
    "typescript": "^5.9.3",
    "vitest": "^3.2.7"
  },
  "dependencies": {
    "commander": "^14.0.2",
    "ws": "^8.21.3",
    "@super-coding/protocol": "0.2.1"
  },
  "scripts": {
    "dev": "tsx watch src/cli.ts",
    "build": "pnpm --filter @super-coding/protocol build && rm -rf dist && tsc -p tsconfig.build.json && node scripts/copy-assets.mjs",
    "fetch-pc": "node scripts/fetch-pc.mjs",
    "link:local": "node scripts/link-local.mjs",
    "start": "node dist/cli.js daemon run",
    "test": "vitest run",
    "typecheck": "tsc --noEmit"
  }
}
